+		if err != nil {
+			continue
+		}
+		if err := rejectSymlinkPathComponents(repoDir, filepath.FromSlash(clean)); err != nil {
+			continue
+		}
+		data, err := os.ReadFile(filepath.Join(repoDir, filepath.FromSlash(clean)))
+		if err != nil {
+			continue
+		}
+		lines := strings.Split(string(data), "\n")
+		start := symbol.StartLine
+		end := symbol.EndLine
+		if end < start {
+			end = start
+		}
+		if start > len(lines) {
+			continue
+		}
+		if end > len(lines) {
+			end = len(lines)
+		}
+		content = append(content, semanticContent{Path: clean, StartLine: start, EndLine: end, Text: strings.Join(lines[start-1:end], "\n")})
+	}
+	return content
+}
